mapper.select:
SELECT

FROM comment c
LEFT JOIN `user` u ON u.id = c.user_id AND u.is_deleted = 0
LEFT JOIN `user` ru ON ru.id = c.reply_user_id AND ru.is_deleted = 0

    c.post_id = #{postId}
    AND c.is_deleted = 0
    AND c.parent_id = 0

        AND (
            c.create_time < #{cursorCreateTime}
            OR (c.create_time = #{cursorCreateTime} AND c.id < #{cursorId})
        )


ORDER BY c.create_time DESC, c.id DESC
LIMIT #{limit}

SELECT

FROM comment c
LEFT JOIN `user` u ON u.id = c.user_id AND u.is_deleted = 0
LEFT JOIN `user` ru ON ru.id = c.reply_user_id AND ru.is_deleted = 0

    c.root_id = #{rootCommentId}
    AND c.is_deleted = 0
    AND c.parent_id <> 0

        AND (
            c.create_time > #{cursorCreateTime}
            OR (c.create_time = #{cursorCreateTime} AND c.id > #{cursorId})
        )


ORDER BY c.create_time ASC, c.id ASC
LIMIT #{limit}

SELECT c.root_id AS root_id, COUNT(*) AS reply_count FROM comment c WHERE c.root_id IN
#{rootId}
AND c.parent_id <> 0 AND c.is_deleted = 0 GROUP BY c.root_id

SELECT

FROM comment c
INNER JOIN post p ON p.id = c.post_id AND p.is_deleted = 0
LEFT JOIN `user` u ON u.id = c.user_id AND u.is_deleted = 0
LEFT JOIN `user` ru ON ru.id = c.reply_user_id AND ru.is_deleted = 0

    c.user_id = #{userId}
    AND c.is_deleted = 0

        AND (
            c.create_time < #{cursorCreateTime}
            OR (c.create_time = #{cursorCreateTime} AND c.id < #{cursorId})
        )


ORDER BY c.create_time DESC, c.id DESC
LIMIT #{limit}
